DROP SCHEMA IF EXISTS `audit` ;
CREATE SCHEMA IF NOT EXISTS `audit` ;

-- ----------------------------------------------------------------------------
-- Table audit.StepLog
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `audit`.`StepLog` (
  `StepLogId` INT NOT NULL,
  `ParentLogId` INT NOT NULL DEFAULT 0,
  `ProcessName` VARCHAR(256) NULL,
  `ProcessType` VARCHAR(256) NULL,
  `StepName` VARCHAR(256) NULL,
  `StepDesc` VARCHAR(0) CHARACTER SET 'utf8mb4' NULL,
  `StepStatus` VARCHAR(10) NULL,
  `StartDtm` DATETIME(6) NOT NULL,
  `DurationInSeconds` INT NULL,
  `DbName` VARCHAR(50) NULL,
  `RecordCount` INT NULL,
  `ETLExecutionId` INT NOT NULL,
  `PathId` INT NOT NULL,
  PRIMARY KEY (`StepLogId`),
  INDEX `IDX_StepLog_ProcessName` (`ProcessName`(255) ASC) VISIBLE,
  INDEX `IDX_NCI_StepLog_Index1` (`StepStatus` ASC, `StepName`(255) ASC, `ETLExecutionId` ASC) VISIBLE);

