-- 	on		 rs.StatusId		= iss.StatusId
-- 	join	 ctl.Publisher		  pr
-- 	on		 pr.PublisherId		= pn.PublisherId
-- 	where	 rs.StatusCode		  in ('IC','IA','IN') 
