-- 	(
-- 		SELECT	 Passphrase
-- 		FROM	 ctl.[Passphrase]
-- 		WHERE	 DatabaseName	= @DbName
-- 		AND		 SchemaName		= @SchemaName
-- 		AND		 TableName		= @PassphraseTableName
-- 	)
-- 
