-- ----------------------------------------------------------------------------
-- View ctl.vw_DelayedPublicationsList
-- ----------------------------------------------------------------------------
-- USE `ctl`;
-- CREATE  OR REPLACE VIEW [ctl].[vw_DelayedPublicationsList] AS
-- 	SELECT p.PublicationId
-- 		,p.PublicationCode
-- 		,p.PublicationName
-- 		,i.LastIssueDtm
-- 		,p.IntervalCode
-- 		,p.IntervalLength
-- 		,p.SLATime
-- 		,p.NextExecutionDtm
-- 		,ElapsedTimePercent = ETP.ElapsedTimePercent
-- 	FROM ctl.Publication AS p
-- 	INNER JOIN (SELECT PublicationId
-- 					  ,max(CreatedDtm) AS LastIssueDtm
-- 				FROM ctl.Issue
-- 				GROUP BY PublicationId) AS i ON i.PublicationId = p.PublicationId
-- 	OUTER APPLY (SELECT ElapsedTimePercent = CASE p.IntervalCode
-- 			WHEN 'MIN'	 THEN ((DATEDIFF(ss, p.NextExecutionDtm, GETDATE()) * 100) / (p.IntervalLength * 60))
-- 			WHEN 'HRLY'	 THEN ((DATEDIFF(mi, p.NextExecutionDtm, GETDATE()) * 100) / (p.IntervalLength * 60))
-- 			WHEN 'DLY'	 THEN ((DATEDIFF(hh, p.NextExecutionDtm, GETDATE()) * 100) / (p.IntervalLength * 24))
-- 			WHEN 'WKLY'	 THEN ((DATEDIFF(hh, p.NextExecutionDtm, GETDATE()) * 100) / (p.IntervalLength * 168))
-- 			WHEN 'MTHLY' THEN ((DATEDIFF(dd, p.NextExecutionDtm, GETDATE()) * 100) / (p.IntervalLength * (DATEDIFF(dd, p.NextExecutionDtm, DATEADD(mm, p.IntervalLength, p.NextExecutionDtm)))))
-- 			WHEN 'YRLY'  THEN ((DATEDIFF(mm, p.NextExecutionDtm, GETDATE()) * 100) / (p.IntervalLength * 12))
-- 			END) ETP
-- 	WHERE IsDataHub = 1
-- 	AND IsActive = 1
-- 	AND ElapsedTimePercent > 50
-- 
-- 
-- /******************************************************************************
--        CHANGE HISTORY
-- *******************************************************************************
-- Date		Author			Description
-- --------	-------------	---------------------------------------------------
-- 20180518	omkar		Initial Iteration
-- 20192002	ochowkwale	Modifying the view to display only records with Elapsed 
-- 						Time greater than 50%
-- 20190624	ochowkwale	Updating view to use IsActive field
-- ******************************************************************************/
-- ;

-- ----------------------------------------------------------------------------
-- View ctl.fn_GetLastSuccessfulIssuePeriodEndDtm
-- ----------------------------------------------------------------------------
-- USE `ctl`;
-- CREATE  OR REPLACE FUNCTION [ctl].[fn_GetLastSuccessfulIssuePeriodEndDtm]
-- (
-- 	   @pInstitutionCode	varchar(50)
-- 	  ,@pPublicationCode	varchar(50)
-- 	  ,@pIsFullLoad			int			= -1
-- 	  --,@pExtraDaysToLoad	int			= 3
-- )	RETURNS DATETIME
-- AS
-- 
-- /*****************************************************************************
-- File:		fn_GetLastSuccessfulIssueLogicalEndDtm.sql
-- Name:		fn_GetLastSuccessfulIssueLogicalEndDtm
-- Purpose:	Pass in a publication code (likely Canvas), and get the PeriodEndTime
-- from the last successful execution. This can be used for filtering data. It checks for 
-- the last execution that was 100% successful.
-- 
-- select ctl.fn_GetLastSuccessfulIssuePeriodEndDtm('AU','SUBMISSIONDIM-AU',0) as PeriodStartTime
-- select ctl.fn_GetLastSuccessfulIssuePeriodEndDtm('AU','SUBMISSIONDIM-AU',1) as PeriodStartTime
-- 
-- select ctl.fn_GetLastSuccessfulIssuePeriodEndDtm('UoR','SUBMISSIONDIM-UoR',0) as PeriodStartTime
-- select ctl.fn_GetLastSuccessfulIssuePeriodEndDtm('AU','DISCUSSIONENTRYDIM-AU',0) as PeriodStartTime
-- 
-- Parameters: @pPublisherCode, @pPublicationCode    
-- 
-- Called by:	Multiple LMS SSIS Stage Packages
-- Calls:		N/A      
-- 
-- Errors:		
-- 
-- Author:		Jeff Prom
-- Date:		2017-10-30
-- *******************************************************************************
--        CHANGE HISTORY
-- *******************************************************************************
-- Date		Author			Description
-- --------	-------------	---------------------------------------------------
-- 2018-01-03	Jeff Prom		Removed the package parameter. we won't be checking the catalog anymore.
-- 							Added PublisherCode parameter. This will be used to check for successful loads.
-- 2018-01-10	Jeff Prom		Came up with version #3
-- 2018-02-12	Jeff Prom		Added @pExtraDaysToLoad. Set it to 3. We found that Canvas can send
-- 							data 42 hours back.
-- 2019-03-07	Omkar Chowkwale	Replaced the logic for finding the last successful IssueId from ETLExecutionId
-- 							to be based on IssueId alone
-- 20201118	ffortunato		removing warnings.
-- ******************************************************************************/
-- 
-- BEGIN
-- 	----------------------------------------------------
-- 	-- Testing
-- 	--DECLARE @pInstitutionCode	varchar(50) = 'AU'
-- 	--DECLARE @pPublicationCode	varchar(50) = 'DISCUSSIONENTRYDIM-AU'
-- 	--DECLARE @pIsFullLoad		INT			= -1
-- 	----------------------------------------------------
-- 
-- 	DECLARE @PeriodStartTime	DATETIME
-- 	DECLARE @ExtraDaysToLoad	int			= 3
-- 		,@IssueId INT
-- 
-- 	IF (@pIsFullLoad = 1)
-- 		SET @PeriodStartTime = cast('1900-01-01' as datetime)
-- 
-- 	ELSE
-- 		BEGIN
-- 
-- 		--Find the last successful IssueId for that publication
-- 		set @IssueId = (
-- 			select		 max(iss.IssueId)
-- 			from		 ctl.Issue						AS iss
-- 			INNER JOIN	 ctl.RefStatus					AS rs	
-- 			ON			 iss.StatusId					 = rs.StatusId
-- 			INNER JOIN	 ctl.Publication				AS pn	
-- 			ON			 iss.PublicationId				 = pn.PublicationId
-- 			where  		 pn.PublicationCode				 = @pPublicationCode
-- 			and			 rs.StatusCode					 = 'IC'
-- 			)
-- 
-- 		-- Now find the PeriodStartTime by Publication using the ETLExecutionID
-- 		select @PeriodStartTime = (
-- 			select	 coalesce(iss.PeriodEndTime, '1900-01-01')		AS PeriodStartTime
-- 			from	 ctl.Issue		AS iss
-- 			where	 iss.IssueId	= @IssueId
-- 		)
-- 
-- 		-- apply extra days to load option
-- 		select @PeriodStartTime = dateadd(dd, -@ExtraDaysToLoad, @PeriodStartTime)
-- 
-- 		-- Testing
-- 		-- select @PeriodStartTime as PeriodStartTime
-- 
-- 		END
-- 
-- 	-- Override (For Testing)
-- 	--SET @PeriodStartTime = '2017-12-01'
-- 	--SET @PeriodStartTime = '1900-01-01'
-- 
-- 
-- 	-- Return the result of the function
-- 	--select @PeriodStartTime
-- 	RETURN coalesce(@PeriodStartTime,'1900-01-01')
-- 
-- END
-- ;

-- ----------------------------------------------------------------------------
-- View ctl.fn_GetLastSuccessfulETLExecutionID
-- ----------------------------------------------------------------------------
-- USE `ctl`;
-- CREATE  OR REPLACE FUNCTION [ctl].[fn_GetLastSuccessfulETLExecutionID]
-- (
-- 	   @pInstitutionCode	varchar(50)
-- 	  ,@pIsFullLoad			INT			= -1
-- )	RETURNS INT
-- AS
-- 
-- /*****************************************************************************
-- File:		fn_GetLastSuccessfulETLExecutionID.sql
-- Name:		fn_GetLastSuccessfulETLExecutionID
-- Purpose:	Pass in an institution code, and get the ETLExecutionID
-- from the last successful execution. This can be used for filtering data. It checks for 
-- the last execution that was 100% successful.
-- 
-- select ctl.fn_GetLastSuccessfulETLExecutionID('AU', 0) as IssueId
-- select ctl.fn_GetLastSuccessfulETLExecutionID('AU', 1) as IssueId
-- 
-- select ctl.fn_GetLastSuccessfulETLExecutionID('UoR', 0) as IssueId
-- select ctl.fn_GetLastSuccessfulETLExecutionID('UoR', 1) as IssueId
-- 
-- Parameters: @pPublisherCode, @pPublicationCode    
-- 
-- Called by:	Multiple LMS SSIS Stage Packages
-- Calls:		N/A      
-- 
-- Errors:		
-- 
-- Author:		Jeff Prom
-- Date:		2018-02-07
-- *******************************************************************************
--        CHANGE HISTORY
-- *******************************************************************************
-- Date		Author			Description
-- --------	-------------	---------------------------------------------------
-- 20201118	ffortunato		cleaning up warnings
-- ******************************************************************************/
-- 
-- BEGIN
-- 	----------------------------------------------------
-- 	-- Testing
-- 	--DECLARE @pInstitutionCode	varchar(50) = 'AU'
-- 	--DECLARE @pIsFullLoad		INT			= 0
-- 	----------------------------------------------------
-- 
-- 	DECLARE @ETLExecutionID		INT				= -1
-- 	DECLARE @StepLogMessage		VARCHAR(256)	= 'Canvas Data Load Complete - ' + @pInstitutionCode
-- 
-- 	IF (@pIsFullLoad = 1)
-- 		SET @ETLExecutionID = -2 -- catch any entries with a -1
-- 
-- 	ELSE
-- 		-- Find the ETLExecutionID from the last successful canvas data load using Step Logs.
-- 		SET		@ETLExecutionID = (
-- 			select max(ETLExecutionId) 
-- 			from	[audit].StepLog 
-- 			where	isnull(StepName,'NoMatch')		= @StepLogMessage 
-- 			and		isnull(StepStatus,'NoMatch')	= 'Success')
-- 
-- 	----------------------------------------------------
-- 	-- Return the result of the function
-- 	--select @ETLExecutionID as ETLExecutionID
-- 	RETURN @ETLExecutionID
-- 
-- END
-- ;

-- ----------------------------------------------------------------------------
-- View ctl.fn_GetIntervalInMinutes
-- ----------------------------------------------------------------------------
-- USE `ctl`;
-- CREATE  OR REPLACE FUNCTION [ctl].[fn_GetIntervalInMinutes] (
-- 	@pIntervalLength INT
-- 	,@pIntervalCode VARCHAR(20)
-- 	,@pETLExecutionId INT = - 1
-- 	,@pPathId INT = - 1
-- 	,@pVerbose BIT = 0
-- 	) RETURNS BIGINT
-- /*****************************************************************************
-- File:		fn_GetIntervalInMinutes.sql
-- Name:		fn_GetIntervalInMinutes
-- Purpose:    Gives the inteval in minutes based on Interval code and Interval Length
-- 
-- select ctl.fn_GetIntervalInMinutes(2,'YRLY',-1,-1,0)
-- 
-- Parameters:	
-- 
-- Called by: ETL
-- Calls:          
-- 
-- Errors:		
-- 
-- Author:		ochowkwale
-- Date:		20190307
-- 
-- *******************************************************************************
--        CHANGE HISTORY
-- *******************************************************************************
-- Date		Author			Description
-- --------	-------------	---------------------------------------------------
-- 20190307	ochowkwale		Initial iteration.
-- 
-- ******************************************************************************/
-- BEGIN
-- 	DECLARE @CurrentDtm DATETIME = GETDATE()
-- 	DECLARE @pIntervalMinutes BIGINT 
-- 
-- 	SELECT @pIntervalMinutes = CASE @pIntervalCode
-- 			WHEN 'MIN'
-- 				THEN @pIntervalLength
-- 			WHEN 'HR'
-- 				THEN DATEDIFF(mi, @CurrentDtm, DATEADD(hh, @pIntervalLength, @CurrentDtm))
-- 			WHEN 'DY'
-- 				THEN DATEDIFF(mi, @CurrentDtm, DATEADD(dd, @pIntervalLength, @CurrentDtm))
-- 			WHEN 'WK'
-- 				THEN DATEDIFF(mi, @CurrentDtm, DATEADD(wk, @pIntervalLength, @CurrentDtm))
-- 			WHEN 'MT'
-- 				THEN DATEDIFF(mi, @CurrentDtm, DATEADD(mm, @pIntervalLength, @CurrentDtm))
-- 			WHEN 'YR'
-- 				THEN DATEDIFF(mi, @CurrentDtm, DATEADD(yyyy, @pIntervalLength, @CurrentDtm))
-- 			WHEN 'IMM'
-- 				THEN 0
-- 			ELSE	 0
-- 			END 
-- 
-- 	RETURN @pIntervalMinutes
-- END
-- ;

-- ----------------------------------------------------------------------------
-- View ctl.fn_GetOutboundFileDate
-- ----------------------------------------------------------------------------
-- USE `ctl`;
-- CREATE  OR REPLACE FUNCTION [ctl].[fn_GetOutboundFileDate] (
-- 		 @pPackageExecutionDtm		datetime
-- 		,@pETLExecutionId			int				= -1
-- 		,@pPathId					int				= -1
-- 		,@pVerbose					bit				= 0)
-- 
-- /*****************************************************************************
-- File:		fn_GetOutboundFileDate.sql
-- Name:		fn_GetOutboundFileDate
-- Purpose:    Gives out the date needed for file creation in format - YYYYMMDDHHMMSS
-- 			This will be appended to the file name
-- 
-- select OutboundFileDate from pg.fn_GetOutboundFileDate(GETDATE(),-1,-1,0)
-- 
-- Parameters:	
-- 
-- Called by: ETL
-- Calls:          
-- 
-- Errors:		
-- 
-- Author:		ochowkwale
-- Date:		20190307
-- 
-- *******************************************************************************
--        CHANGE HISTORY
-- *******************************************************************************
-- Date		Author			Description
-- --------	-------------	---------------------------------------------------
-- 20190307	ochowkwale		Initial iteration.
-- 
-- ******************************************************************************/
-- 
-- RETURNS @ReturnTable TABLE (OutboundFileDate BIGINT) AS
-- 
-- BEGIN
-- 	INSERT INTO @ReturnTable
-- 	SELECT replace(replace(replace(convert(VARCHAR(19), @pPackageExecutionDtm, 126), '-', ''), 'T', ''), ':', '') OutboundFileDate
-- 	RETURN
-- END
-- ;

-- ----------------------------------------------------------------------------
-- View ctl.GetIssueNamesToRetrieve
-- ----------------------------------------------------------------------------
-- USE `ctl`;
-- CREATE  OR REPLACE PROCEDURE [ctl].[GetIssueNamesToRetrieve] (
-- 		 @pIssueNameLookup		ctl.udt_IssueNameLookup READONLY
-- 		,@pPublicationCode      varchar(50)     = 'N/A'
-- 		,@pLookBack				datetime		= Null
-- 		,@pETLExecutionId		int				= -1
-- 		,@pPathId				int				= -1
-- 		,@pVerbose				bit				= 0)
-- AS
-- /*****************************************************************************
-- File:		GetIssueNamesToRetrieve.sql
-- Name:		GetIssueNamesToRetrieve
-- 
-- Purpose:	This procedure accpets a list of files that datahub has found on a 
-- 			publisher file share (noramlly ftp / sftp site). The procedure 
-- 			returns a subset list of those files that have not been processed.
-- 			This list will be used by powersehll to inititate a file transfer.
-- 
-- exec:
-- 
-- 	declare @MyTable [ctl].[udt_IssueNameLookup]
-- 
-- 	insert into @MyTable
-- 	select 'Frank','Open',getdate()
-- 
-- 	select * from @MyTable
-- 
-- 	exec ctl.GetIssueNamesToRetrieve
-- 			 @pIssueNameLookup		= @MyTable
-- 			,@pPublicationCode      = 'N/A'
-- 			,@pLookBack				= Null
-- 			,@pETLExecutionId		= -1
-- 			,@pPathId				= -1
-- 			,@pVerbose				= 0
-- 
-- Parameters:   
-- 			 @pIssueNameLookup		Table of vaules to be processed
-- 			,@pPublicationCode      Publication Codes to be evaulated
-- 			,@pLookBack				Determines how far back you want to search for a file.
-- 			,@pETLExecutionId		 
-- 			,@pPathId				 
-- 			,@pVerbose				 
-- 
-- Called by:	DataHub powershell scripts
-- Calls:          
-- 
-- Errors:		
-- 
-- Author:		
-- Date:		
-- 
-- *******************************************************************************
--        CHANGE HISTORY
-- *******************************************************************************
-- Date		Author			Description
-- --------	-------------	---------------------------------------------------
-- 20180222	ffortunato		getting ready for build. 23
-- 20180705	ffortunato		Need to preserver the order the fils came in.
-- 							Modifying the input table to include LastWriteTime
-- 20180906	ffortunato		code validation changes dbnam varchar(20) 
-- 							message (20).
-- 20181004	ffortunato		changing in clause to where exists. Improving join.
-- ******************************************************************************/
-- 
-- -------------------------------------------------------------------------------
-- --  Declarations
-- -------------------------------------------------------------------------------
-- 
-- DECLARE	 @Rows					int				= 0
--         ,@ErrNum				int				= -1
-- 		,@ErrMsg				nvarchar(max)	= 'N/A'
-- 		,@ParametersPassedChar	varchar(1000)   = 'N/A'
-- 		,@CRLF					varchar(10)		= char(13) + char(10)
-- 		,@ProcName				varchar(256)	= OBJECT_NAME(@@PROCID) 
-- 		,@ParentStepLogId       int				= -1
-- 		,@PrevStepLog			int				= -1
-- 		,@ProcessStartDtm		datetime		= getdate()
-- 		,@CurrentDtm			datetime		= getdate()
-- 		,@PreviousDtm			datetime		= getdate()
-- 		,@DbName				varchar(50)		= DB_NAME()
-- 		,@ProcessType			varchar(10)		= 'Proc'
-- 		,@StepName				varchar(256)	= 'Start'
-- 		,@StepOperation			varchar(50)		= 'N/A' 
-- 		,@MessageType			varchar(20)		= 'Info' -- ErrCust, ErrSQL, Info, Warn
-- 		,@StepDesc				nvarchar(2048)	= 'Procedure started' 
-- 		,@StepStatus			varchar(10)		= 'Success'
-- 		,@StepNumber			varchar(10)		= 0
-- 		,@Duration				varchar(10)		= 0
-- 		,@JSONSnippet			nvarchar(max)	= NULL
-- 
-- -------------------------------------------------------------------------------
-- --  Initializations
-- -------------------------------------------------------------------------------
-- 
-- SELECT	 @ParametersPassedChar	= 
-- 			'exec bpi_dw_stage.ctl.GetIssueNamesToRetrieve' + @CRLF +
-- 			'     @pETLExecutionId = ' + isnull(cast(@pETLExecutionId as varchar(100)),'NULL') + @CRLF + 
-- 			'    ,@pPathId = ' + isnull(cast(@pPathId as varchar(100)),'NULL') + @CRLF + 
-- 			'    ,@pVerbose = ' + isnull(cast(@pVerbose as varchar(100)),'NULL')
-- 
-- if @pVerbose					= 1
-- 	begin 
-- 		print @ParametersPassedChar
-- 	end
-- 
-- -------------------------------------------------------------------------------
-- --  Main
-- -------------------------------------------------------------------------------
-- 
-- begin try
-- 
-- 	if @pLookBack is null
-- 		set @pLookBack = dateadd (d,-180,getdate())
-- 
-- -------------------------------------------------------------------------------
-- --  Step comment
-- -------------------------------------------------------------------------------
-- 	select	 @StepName			= 'Select files to download'
-- 			,@StepNumber		= @StepNumber + 1
-- 			,@StepOperation		= 'Operation'
-- 			,@StepDesc			= 'Compares input list to ctl.issue and outputs any files not already staged.'
-- 
-- 	select	 IssueName			as IssueName
-- 			,'Get'				as FileAction
-- 			,FileCreatedDtm		as FileCreatedDtm
-- 	from	 @pIssueNameLookup	  inl
-- 	where	 not exists (
-- 		select	 top 1 1 
-- 		from	 ctl.Issue			  i
-- 		join	 ctl.Publication	  pn
-- 		on		 i.PublicationId	= pn.PublicationId
-- 		where	 pn.PublicationCode = @pPublicationCode
-- 		and		 i.CreatedDtm		> @pLookBack
-- 		and		 inl.IssueName      = i.IssueName)
-- /*
-- 	where	 inl.IssueName		  not in (
-- 		select	 i.IssueName
-- 		from	 ctl.Issue			  i
-- 		join	 ctl.Publication	  pn
-- 		on		 pn.PublicationCode = @pPublicationCode
-- 		where	 i.CreatedDtm		> @pLookBack)
-- */
-- 	-- Upon completion of the step, log it!
-- 	select	 @PreviousDtm		= @CurrentDtm
-- 			,@Rows				= @@ROWCOUNT 
-- 	select	 @CurrentDtm		= getdate()
-- 			--,@JSONSnippet		= '<JSON Snippet>' -- Only if needed.
-- /*
-- 			-- TESTING
-- 			declare @x varchar(299)
-- 			select top 1 @x= 'Issue: ' + IssueName from @pIssueNameLookup 
-- 			select @x=@x + ' Rows: ' + CAST(@Rows AS VARCHAR(10))
-- 			select @JSONSnippet	 = '{"Dump":"'+@x+'"}'
-- */
-- 
-- 	exec [audit].usp_InsertStepLog
-- 			 @MessageType		,@CurrentDtm		,@PreviousDtm	,@StepNumber		,@StepOperation		,@JSONSnippet		,@ErrNum
-- 			,@ParametersPassedChar					,@ErrMsg output	,@ParentStepLogId	,@ProcName			,@ProcessType		,@StepName
-- 			,@StepDesc output	,@StepStatus		,@DbName		,@Rows				,@pETLExecutionId	,@pPathId			,@PrevStepLog output
-- 			,@pVerbose
-- 
-- 	select	 @JSONSnippet		= NULL
-- 
-- end try
-- 
-- -------------------------------------------------------------------------------
-- --  Error Handling
-- -------------------------------------------------------------------------------
-- begin catch
-- 
-- 	select 	 @PreviousDtm		= @CurrentDtm
-- 			,@ErrNum			= @@ERROR
-- 			,@ErrMsg			= ERROR_MESSAGE()
-- 			,@Rows				= 0
-- 
-- 	select	 @StepStatus		= 'Failure'
-- 			,@CurrentDtm		= getdate()
-- 
-- 	if		 @MessageType		<> 'ErrCust'
-- 		select   @MessageType	= 'ErrSQL'
-- 
-- 	exec [audit].usp_InsertStepLog
-- 			 @MessageType		,@CurrentDtm		,@PreviousDtm	,@StepNumber		,@StepOperation		,@JSONSnippet		,@ErrNum
-- 			,@ParametersPassedChar					,@ErrMsg output	,@ParentStepLogId	,@ProcName			,@ProcessType		,@StepName
-- 			,@StepDesc output	,@StepStatus		,@DbName		,@Rows				,@pETLExecutionId	,@pPathId			,@PrevStepLog output
-- 			,@pVerbose
-- 
-- 	if 	@ErrNum < 50000	
-- 		select	 @ErrNum	= @ErrNum + 100000000 -- Need to increase number to throw message.
-- 
-- 	;throw	 @ErrNum, @ErrMsg, 1
-- 	
-- end catch
-- 
-- -------------------------------------------------------------------------------
-- --  Procedure End
-- -------------------------------------------------------------------------------
-- ;

-- ----------------------------------------------------------------------------
-- View ctl.usp_GetParameterListing
-- ----------------------------------------------------------------------------
-- USE `ctl`;
-- create  OR REPLACE procedure [ctl].[usp_GetParameterListing](
-- 		 @pObjectName varchar(255)
-- 		,@pParameterString nvarchar(max) output
-- 		,@pVerbose bit = 0
-- )
-- 
-- as
-- /*****************************************************************************
--  File:           usp_GetParameterListing.sql
--  Name:           usp_GetParameterListing
--  Purpose:        Gets all parameters passed and their values.
-- 
--  declare @pParameterString nvarchar(4000)
-- 	exec ctl.[usp_GetParameterListing]  [usp_insertnewcontact] ,@pParameterString output, 1
-- 	print @pParameterString
-- 
--  Parameters:    
-- 
-- 
-- 
--  Called by:      Application
--  Calls:          
-- 
--  Author:         ffortunato
--  Date:           20161114
-- *******************************************************************************
--        CHANGE HISTORY
-- *******************************************************************************
--  Date      Author         Description
--  --------	-------------	---------------------------------------------------
--  20161114	ffortunato		Original draft
--  20170322	ffortunato		Adding special processing for datetime fields.
-- 							Identifying output variables.
-- 20201119	ffortunato		cleaning up.
-- 
-- ******************************************************************************/
-- begin
-- 
-- declare	@ParameterList table 
-- (
-- 	 ObjectType						nvarchar(60)
-- 	,ParameterName					nvarchar(128)
-- 	,ParameterId					int					not null default -1
-- 	,ParameterDataType				nvarchar(128)
-- 	,IsOutput						bit
-- 	,SchemaName						nvarchar(200)
-- )
-- 
-- declare	 @ParameterString			nvarchar(max)
-- 		,@Max						int
-- 		,@Cnt						int
-- 		,@parameterpassedchar		varchar(4000)
-- 		,@LiteralCRLF				varchar(20)
-- 		,@CRLF						nvarchar(20)
-- 		,@CurrentParameterName		varchar(255)
-- 		,@CurrentParameterType		varchar(255)
-- 		,@CurrentParameterOutput	int 
-- 		,@CurrentParameterSchema    varchar(200)
-- 		,@Tab						varchar(5)	= '    ' -- char(9)
-- 		,@2Tab						varchar(8)	= '        ' -- char(9) + char(9)
-- 		,@3Tab						varchar(12)	= '            ' -- char(9) + char(9) + char(9)
-- 		,@ParmLength				int = -1
-- 		,@TabLenght					int = 4
-- 		,@MaxParmLength				int = -1
-- 		,@TargetTabLength			int = -1
-- 		,@TabsToAddCount			int = -1
-- 		,@TabsToAddChar				varchar(20)
-- 
-- select	@ParameterString		= 'No Parameters Passed to Procedure.'
-- 		,@Max = -1
-- 		,@Cnt = -1
-- 		,@CRLF =  char(13) + char(10) -- CR + LF
-- 		,@LiteralCRLF = 'char(13) + char(10)'
-- 		,@parameterpassedchar  = '***** Parameters Passed to usp_GetParameterListing' + @CRLF +
-- 								'@pObjectName = ''' + isnull(@pObjectName ,'NULL') + '''' + @CRLF + 
-- 								'@pParameterString = ''' + isnull(@pParameterString ,'NULL') + '''' + @CRLF + 
-- 								'@pVerbose = ' + isnull(cast(@pVerbose as varchar(100)),'NULL') + @CRLF + 
-- 								'***** End of Parameters' + @CRLF
-- 
-- print @parameterpassedchar
-- 
-- insert into @ParameterList (
-- 		 ObjectType
-- 		,ParameterName
-- 		,ParameterId
-- 		,ParameterDataType
-- 		,IsOutput
-- 		,SchemaName)
-- SELECT 	SO.type_desc			ObjectType,
-- 		P.name					ParameterName,
-- 		P.parameter_id			ParameterID,
-- 		TYPE_NAME(P.user_type_id) ParameterDataType,
-- 		is_output,
-- 		S.name					SchemaName
-- FROM	sys.objects				  SO
-- JOIN	sys.parameters			  P 
-- ON		SO.object_id			= P.object_id
-- join    sys.schemas				  S
-- on		SO.schema_id			= S.schema_id
-- WHERE	SO.object_id IN (
-- 	SELECT object_id 
-- 	FROM sys.objects
-- 	WHERE type IN ('P','FN'))
-- and		SO.name					= @pObjectName
-- ORDER BY P.parameter_id
-- 
-- -- select  * from @ParameterList
-- 
-- if exists (select top 1 1 from @ParameterList)
-- 	begin
-- 		select	 @Cnt			= 1
-- 				,@Max			= (select max(ParameterId) from @ParameterList)
-- 
-- 		select @CurrentParameterSchema = (select SchemaName
-- 								from @ParameterList
-- 								where ParameterId = @Cnt)	
-- 
-- 
-- 		select @ParameterString	= @CRLF + @3Tab + '''***** Parameters Passed to exec '+ @CurrentParameterSchema +'.' + @pObjectName + ''' + @CRLF +' + @CRLF
-- 
-- 		select @MaxParmLength	= max(len(ParameterName)) + 2 from @ParameterList
-- 		select @TargetTabLength	= (@MaxParmLength / @TabLenght) + 1
-- 
-- /*	
-- 		if @MaxParmLength % @TabLenght = 0 begin
-- 			select @TargetTabLength = @TargetTabLength + 1 --falls on a tab level so add one.
-- 		end
-- */
-- 		
-- 		print  '@MaxParmLength : ' + cast(@MaxParmLength as varchar(100))
-- 		print  '@TargetTabLength : ' + cast(@TargetTabLength as varchar(100))
-- 	end
-- 
-- 
-- 	
-- 
-- while  @Cnt <= @Max and @Cnt <> -1
-- 	begin
-- 		--if @Cnt = 1 select @ParameterString = ' char(13) + '
-- 
-- 		select @CurrentParameterName = (select ParameterName
-- 								from @ParameterList
-- 								where ParameterId = @Cnt)
-- 		select @CurrentParameterType = (select ParameterDataType
-- 								from @ParameterList
-- 								where ParameterId = @Cnt)
-- 		select @CurrentParameterOutput = (select IsOutput
-- 								from @ParameterList
-- 								where ParameterId = @Cnt)
-- 	
-- /*
-- 		select @ParmLength = 0, @TabsToAddCount = 0 , @TabsToAddChar =''
-- 
-- 		select @ParmLength		= len(@CurrentParameterName)
-- -- HERE	
-- 		
-- 		select @TabsToAddCount	= (@TargetTabLength - (@ParmLength / @TabLenght) )
-- 
-- 		if @ParmLength % @TabLenght = 0 begin
-- 			select @TabsToAddCount = @TabsToAddCount + 1 --falls on a tab level so add one.
-- 			--print '% = 0'
-- 		end
-- 		
-- 		select @TabsToAddChar = case @TabsToAddCount 
-- 								when 1 then @Tab
-- 								when 2 then @2Tab
-- 								when 3 then @3Tab
-- 								else @3Tab end
-- 
-- 		print   @CurrentParameterName
-- 		+  '	(@ParmLength / @TabLenght)' + cast(@ParmLength / @TabLenght as varchar(100))
-- 		+  '	@ParmLength : ' + cast(@ParmLength as varchar(100))
-- 		+  '	@TabsToAddCount : ' + cast(@TabsToAddCount as varchar(100))
-- 		+  '	@TabsToAddChar : ' + cast(@TabsToAddChar as varchar(100))
-- */
-- 		if @Cnt = 1 
-- 			select @ParameterString	= @ParameterString + @3Tab + '''' + @Tab + ' ' + @CurrentParameterName --+ @TabsToAddChar
-- 		else 
-- 			select @ParameterString	= @ParameterString + @3Tab + '''' + @Tab + ',' + @CurrentParameterName --+ @TabsToAddChar
-- 		
-- 		if @CurrentParameterOutput = 0 begin
-- 
-- 			if @CurrentParameterType in ('varchar','char','nvarchar') begin 
-- 				select @ParameterString	= @ParameterString + ' = ' + ''''''' + isnull('
-- 				select @ParameterString	= @ParameterString + @CurrentParameterName
-- 				select @ParameterString	= @ParameterString + ' ,''NULL'') + '''''''' + @CRLF + ' + @CRLF
-- 			end else if @CurrentParameterType in ('int','bit','bigint') begin 
-- 				select @ParameterString	= @ParameterString + ' = ' + ''' + isnull(cast('
-- 				select @ParameterString	= @ParameterString + @CurrentParameterName
-- 				select @ParameterString	= @ParameterString + ' as varchar(100)),''NULL'') + @CRLF + ' + @CRLF
-- 			end else if @CurrentParameterType in ('datetime') begin 
-- 				select @ParameterString	= @ParameterString + ' = ' + ''''''' + isnull(convert(varchar(100),'
-- 				select @ParameterString	= @ParameterString + @CurrentParameterName
-- 				select @ParameterString	= @ParameterString + ' ,13) ,''NULL'') + '''''''' + @CRLF + ' + @CRLF
-- 			end else begin
-- 				select @ParameterString	= @ParameterString + ' = ' + ''' + isnull(cast('
-- 				select @ParameterString	= @ParameterString + @CurrentParameterName
-- 				select @ParameterString	= @ParameterString + ' as varchar(100)),''NULL'') + @CRLF + ' + @CRLF
-- 			end
-- 
-- 		end
-- 
-- 		else if @CurrentParameterOutput = 1 begin
