-- 		,@StepName				varchar(256)	= 'Start'
-- 		,@StepOperation			varchar(50)		= 'N/A' 
-- 		,@MessageType			varchar(20)		= 'Info' -- ErrCust, ErrSQL, Info, Warn
-- 		,@StepDesc				nvarchar(2048)	= 'Procedure started' 
