-- 		,@PublicationCode		varchar(50)		= 'N/A'
-- 		
-- declare @RetryPublications table (
-- 		 PublicationId			int
-- 		,StatusCode				VARCHAR(20)
-- 		,IssueId				int)
-- 
-- declare	@IssueDetail			table(
-- 		 IssueDetailId			int identity(1,1)
