-- ******************************************************************************/
-- 
-- -------------------------------------------------------------------------------
-- --  Declarations and Initializations.
-- -------------------------------------------------------------------------------
-- SET NOCOUNT ON
-- 
-- declare	 @Rows					int				= 0
--         ,@ErrNum				int				= -1
-- 		,@ErrMsg				nvarchar(max)	= 'N/A'
-- 		,@ParametersPassedChar	varchar(1000)   = 'N/A'
