-- --------	-------------	---------------------------------------------------
-- 2018-01-03	Jeff Prom		Removed the package parameter. we won't be checking the catalog anymore.
-- 							Added PublisherCode parameter. This will be used to check for successful loads.
-- 2018-01-10	Jeff Prom		Came up with version #3
-- 2018-02-12	Jeff Prom		Added @pExtraDaysToLoad. Set it to 3. We found that Canvas can send
-- 							data 42 hours back.
-- 2019-03-07	Omkar Chowkwale	Replaced the logic for finding the last successful IssueId from ETLExecutionId
-- 							to be based on IssueId alone
-- 20201118	ffortunato		removing warnings.
-- ******************************************************************************/
-- 
-- BEGIN
-- 	----------------------------------------------------
-- 	-- Testing
-- 	--DECLARE @pInstitutionCode	varchar(50) = 'AU'
-- 	--DECLARE @pPublicationCode	varchar(50) = 'DISCUSSIONENTRYDIM-AU'
-- 	--DECLARE @pIsFullLoad		INT			= -1
-- 	----------------------------------------------------
-- 
-- 	DECLARE @PeriodStartTime	DATETIME
-- 	DECLARE @ExtraDaysToLoad	int			= 3
-- 		,@IssueId INT
-- 
-- 	IF (@pIsFullLoad = 1)
-- 		SET @PeriodStartTime = cast('1900-01-01' as datetime)
-- 
-- 	ELSE
-- 		BEGIN
-- 
-- 		--Find the last successful IssueId for that publication
-- 		set @IssueId = (
-- 			select		 max(iss.IssueId)
-- 			from		 ctl.Issue						AS iss
-- 			INNER JOIN	 ctl.RefStatus					AS rs	
-- 			ON			 iss.StatusId					 = rs.StatusId
-- 			INNER JOIN	 ctl.Publication				AS pn	
-- 			ON			 iss.PublicationId				 = pn.PublicationId
-- 			where  		 pn.PublicationCode				 = @pPublicationCode
-- 			and			 rs.StatusCode					 = 'IC'
-- 			)
-- 
-- 		-- Now find the PeriodStartTime by Publication using the ETLExecutionID
-- 		select @PeriodStartTime = (
-- 			select	 coalesce(iss.PeriodEndTime, '1900-01-01')		AS PeriodStartTime
-- 			from	 ctl.Issue		AS iss
-- 			where	 iss.IssueId	= @IssueId
-- 		)
-- 
-- 		-- apply extra days to load option
-- 		select @PeriodStartTime = dateadd(dd, -@ExtraDaysToLoad, @PeriodStartTime)
-- 
-- 		-- Testing
-- 		-- select @PeriodStartTime as PeriodStartTime
-- 
-- 		END
-- 
-- 	-- Override (For Testing)
-- 	--SET @PeriodStartTime = '2017-12-01'
-- 	--SET @PeriodStartTime = '1900-01-01'
-- 
-- 
-- 	-- Return the result of the function
-- 	--select @PeriodStartTime
-- 	RETURN coalesce(@PeriodStartTime,'1900-01-01')
-- 
-- END
-- $$
-- 
-- DELIMITER ;
-- 
-- ----------------------------------------------------------------------------
-- Routine ctl.fn_GetLastSuccessfulETLExecutionID
-- ----------------------------------------------------------------------------
-- DELIMITER $$
-- 
-- DELIMITER $$
-- USE `ctl`$$
-- CREATE FUNCTION [ctl].[fn_GetLastSuccessfulETLExecutionID]
-- (
-- 	   @pInstitutionCode	varchar(50)
-- 	  ,@pIsFullLoad			INT			= -1
-- )	RETURNS INT
-- AS
-- 
-- /*****************************************************************************
-- File:		fn_GetLastSuccessfulETLExecutionID.sql
-- Name:		fn_GetLastSuccessfulETLExecutionID
-- Purpose:	Pass in an institution code, and get the ETLExecutionID
-- from the last successful execution. This can be used for filtering data. It checks for 
-- the last execution that was 100% successful.
-- 
-- select ctl.fn_GetLastSuccessfulETLExecutionID('AU', 0) as IssueId
-- select ctl.fn_GetLastSuccessfulETLExecutionID('AU', 1) as IssueId
-- 
-- select ctl.fn_GetLastSuccessfulETLExecutionID('UoR', 0) as IssueId
-- select ctl.fn_GetLastSuccessfulETLExecutionID('UoR', 1) as IssueId
-- 
-- Parameters: @pPublisherCode, @pPublicationCode    
-- 
-- Called by:	Multiple LMS SSIS Stage Packages
-- Calls:		N/A      
-- 
-- Errors:		
-- 
-- Author:		Jeff Prom
-- Date:		2018-02-07
-- *******************************************************************************
--        CHANGE HISTORY
-- *******************************************************************************
-- Date		Author			Description
-- --------	-------------	---------------------------------------------------
-- 20201118	ffortunato		cleaning up warnings
-- ******************************************************************************/
-- 
-- BEGIN
-- 	----------------------------------------------------
-- 	-- Testing
-- 	--DECLARE @pInstitutionCode	varchar(50) = 'AU'
-- 	--DECLARE @pIsFullLoad		INT			= 0
-- 	----------------------------------------------------
-- 
-- 	DECLARE @ETLExecutionID		INT				= -1
-- 	DECLARE @StepLogMessage		VARCHAR(256)	= 'Canvas Data Load Complete - ' + @pInstitutionCode
-- 
-- 	IF (@pIsFullLoad = 1)
-- 		SET @ETLExecutionID = -2 -- catch any entries with a -1
-- 
-- 	ELSE
-- 		-- Find the ETLExecutionID from the last successful canvas data load using Step Logs.
-- 		SET		@ETLExecutionID = (
-- 			select max(ETLExecutionId) 
-- 			from	[audit].StepLog 
-- 			where	isnull(StepName,'NoMatch')		= @StepLogMessage 
-- 			and		isnull(StepStatus,'NoMatch')	= 'Success')
-- 
-- 	----------------------------------------------------
-- 	-- Return the result of the function
-- 	--select @ETLExecutionID as ETLExecutionID
-- 	RETURN @ETLExecutionID
-- 
-- END
-- $$
-- 
-- DELIMITER ;
-- 
-- ----------------------------------------------------------------------------
-- Routine ctl.fn_GetIntervalInMinutes
-- ----------------------------------------------------------------------------
-- DELIMITER $$
-- 
-- DELIMITER $$
-- USE `ctl`$$
-- CREATE FUNCTION [ctl].[fn_GetIntervalInMinutes] (
-- 	@pIntervalLength INT
-- 	,@pIntervalCode VARCHAR(20)
-- 	,@pETLExecutionId INT = - 1
-- 	,@pPathId INT = - 1
-- 	,@pVerbose BIT = 0
-- 	) RETURNS BIGINT
-- /*****************************************************************************
-- File:		fn_GetIntervalInMinutes.sql
-- Name:		fn_GetIntervalInMinutes
-- Purpose:    Gives the inteval in minutes based on Interval code and Interval Length
-- 
-- select ctl.fn_GetIntervalInMinutes(2,'YRLY',-1,-1,0)
-- 
-- Parameters:	
-- 
-- Called by: ETL
-- Calls:          
-- 
-- Errors:		
-- 
-- Author:		ochowkwale
-- Date:		20190307
-- 
-- *******************************************************************************
--        CHANGE HISTORY
-- *******************************************************************************
-- Date		Author			Description
-- --------	-------------	---------------------------------------------------
-- 20190307	ochowkwale		Initial iteration.
-- 
-- ******************************************************************************/
-- BEGIN
-- 	DECLARE @CurrentDtm DATETIME = GETDATE()
-- 	DECLARE @pIntervalMinutes BIGINT 
-- 
-- 	SELECT @pIntervalMinutes = CASE @pIntervalCode
-- 			WHEN 'MIN'
-- 				THEN @pIntervalLength
-- 			WHEN 'HR'
-- 				THEN DATEDIFF(mi, @CurrentDtm, DATEADD(hh, @pIntervalLength, @CurrentDtm))
-- 			WHEN 'DY'
-- 				THEN DATEDIFF(mi, @CurrentDtm, DATEADD(dd, @pIntervalLength, @CurrentDtm))
-- 			WHEN 'WK'
-- 				THEN DATEDIFF(mi, @CurrentDtm, DATEADD(wk, @pIntervalLength, @CurrentDtm))
-- 			WHEN 'MT'
-- 				THEN DATEDIFF(mi, @CurrentDtm, DATEADD(mm, @pIntervalLength, @CurrentDtm))
-- 			WHEN 'YR'
-- 				THEN DATEDIFF(mi, @CurrentDtm, DATEADD(yyyy, @pIntervalLength, @CurrentDtm))
-- 			WHEN 'IMM'
-- 				THEN 0
-- 			ELSE	 0
-- 			END 
-- 
-- 	RETURN @pIntervalMinutes
-- END
-- $$
-- 
-- DELIMITER ;
-- 
-- ----------------------------------------------------------------------------
-- Routine ctl.fn_GetOutboundFileDate
-- ----------------------------------------------------------------------------
-- DELIMITER $$
-- 
-- DELIMITER $$
-- USE `ctl`$$
-- CREATE FUNCTION [ctl].[fn_GetOutboundFileDate] (
-- 		 @pPackageExecutionDtm		datetime
-- 		,@pETLExecutionId			int				= -1
-- 		,@pPathId					int				= -1
-- 		,@pVerbose					bit				= 0)
-- 
-- /*****************************************************************************
-- File:		fn_GetOutboundFileDate.sql
-- Name:		fn_GetOutboundFileDate
-- Purpose:    Gives out the date needed for file creation in format - YYYYMMDDHHMMSS
-- 			This will be appended to the file name
-- 
-- select OutboundFileDate from pg.fn_GetOutboundFileDate(GETDATE(),-1,-1,0)
-- 
-- Parameters:	
-- 
-- Called by: ETL
-- Calls:          
-- 
-- Errors:		
-- 
-- Author:		ochowkwale
-- Date:		20190307
-- 
-- *******************************************************************************
--        CHANGE HISTORY
-- *******************************************************************************
-- Date		Author			Description
-- --------	-------------	---------------------------------------------------
-- 20190307	ochowkwale		Initial iteration.
-- 
-- ******************************************************************************/
-- 
-- RETURNS @ReturnTable TABLE (OutboundFileDate BIGINT) AS
-- 
-- BEGIN
-- 	INSERT INTO @ReturnTable
-- 	SELECT replace(replace(replace(convert(VARCHAR(19), @pPackageExecutionDtm, 126), '-', ''), 'T', ''), ':', '') OutboundFileDate
-- 	RETURN
-- END
-- $$
-- 
-- DELIMITER ;
