-- ----------------------------------------------------------------------------
-- Trigger ctl.trg_IssueStatusUpdateFail
-- ----------------------------------------------------------------------------
-- DELIMITER $$
-- USE `ctl`$$
-- 
-- 
-- CREATE TRIGGER [ctl].[trg_IssueStatusUpdateFail] ON [ctl].[Issue] FOR  UPDATE AS
-- /******************************************************************************
-- file:           trg_IssueStatusUpdateFail.sql
-- name:           trg_IssueStatusUpdateFail
-- 
-- purpose:        this trigger sits on the Issue table. when a 
-- 				issue status is updated to failed, the trigger updates the IssueName
-- 				in issue table, updates distribution status to Fail, updates posting 
-- 				group status to Fail.
-- 
-- called by:      update on ctl.issue
-- calls:          
-- 
-- author:         ochowkwale
-- date:           20200708
-- 
-- *******************************************************************************
--        change history
-- *******************************************************************************
-- date		author			description
-- --------	-------------	---------------------------------------------------
-- 20200708	ochowkwale		initial iteration
-- ******************************************************************************/
-- 
-- declare 
--      @err						int				= 0
--     ,@ErrMsg					varchar(255)	= 'trigger trg_IssueStatusUpdateFail (trigger) failed.' + Char(13)
--     ,@Start						datetime		= GETDATE()
--     ,@CreatedBy					varchar(30)		= SYSTEM_USER
-- 	,@Verbose					bit				= 0
-- 
-- 
-- begin try
-- 	
-- 	select	 ins.IssueId
-- 	INTO #IssueId
-- 	from	 inserted				  ins
-- 	join	 ctl.RefStatus			  rs
-- 	on		 ins.StatusId			= rs.StatusId
-- 	WHERE rs.StatusCode = 'IF'
-- 	AND ins.IssueName NOT LIKE 'IF_%'
-- 
-- 	--Update the Issuename to inlcude status and IssueId
-- 	UPDATE i
-- 	SET IssueName = CONCAT('IF_',i.IssueId,'_',i.IssueName)
-- 		,ModifiedBy = SYSTEM_USER
-- 		,ModifiedDtm = GETDATE()
-- 	FROM ctl.Issue as i
-- 	INNER JOIN #IssueId on #IssueId.IssueId = i.IssueId
-- 
-- end try
-- 
-- begin catch
-- 	select @ErrMsg	= @ErrMsg + char(13)  + 	
-- 					' @IssueId = ' + isnull(cast((select top 1 IssueId from #IssueId) as varchar(100)),'NULL') + ' ' + 
-- 					' @IssueStatusCode = IF'
-- 	select @ErrMsg = @ErrMsg + char(13)  + ERROR_MESSAGE()
-- 	raiserror (@ErrMsg,-1,-1)
-- 
-- end catch
-- ;

-- ----------------------------------------------------------------------------
-- Schema pg
-- ----------------------------------------------------------------------------
DROP SCHEMA IF EXISTS `pg` ;
CREATE SCHEMA IF NOT EXISTS `pg` ;

-- ----------------------------------------------------------------------------
-- Table pg.RefProcessingMode
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `pg`.`RefProcessingMode` (
  `ProcessingModeId` INT NOT NULL,
  `ProcessingModeCode` VARCHAR(20) NOT NULL,
  `ProcessingModeName` VARCHAR(250) NOT NULL,
  `ProcessingModeDesc` VARCHAR(1000) NOT NULL,
  `CreatedBy` VARCHAR(50) NOT NULL,
  `CreatedDtm` DATETIME(6) NOT NULL,
  `ModifiedBy` VARCHAR(50) NULL,
  `ModifiedDtm` DATETIME(6) NULL,
  PRIMARY KEY (`ProcessingModeCode`));

-- ----------------------------------------------------------------------------
-- Table pg.PostingGroupProcessing
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `pg`.`PostingGroupProcessing` (
  `PostingGroupProcessingId` BIGINT NOT NULL,
  `PostingGroupBatchId` INT NOT NULL,
  `PostingGroupId` INT NOT NULL,
  `PostingGroupStatusId` INT NOT NULL DEFAULT -1,
  `PGPBatchSeq` BIGINT NOT NULL DEFAULT 1,
  `SrcBatchSeq` BIGINT NOT NULL DEFAULT 1,
  `ProcessingModeCode` VARCHAR(20) NOT NULL DEFAULT 'NORM',
  `DateId` INT NOT NULL,
  `StartTime` DATETIME(6) NULL,
  `EndTime` DATETIME(6) NULL,
  `DurationChar` VARCHAR(20) NOT NULL DEFAULT '00:00:00',
  `DurationSec` INT NOT NULL DEFAULT -1,
  `RecordCount` INT NOT NULL DEFAULT -1,
  `RetryCount` INT NOT NULL DEFAULT 0,
  `IssueId` BIGINT NOT NULL DEFAULT -1,
  `DistributionId` BIGINT NOT NULL DEFAULT -1,
  `ETLExecutionId` INT NULL,
  `CreatedBy` VARCHAR(50) NOT NULL,
  `CreatedDtm` DATETIME(6) NOT NULL,
  `ModifiedBy` VARCHAR(50) NULL,
  `ModifiedDtm` DATETIME(6) NULL,
  PRIMARY KEY (`PostingGroupProcessingId`),
  INDEX `idx_PGP_PGID` (`PostingGroupId` ASC, `PostingGroupBatchId` ASC, `PostingGroupStatusId` ASC) VISIBLE,
  UNIQUE INDEX `UQ_PGP__ProcessingId_BatchId_BatchSeq` (`PostingGroupBatchId` ASC, `PostingGroupId` ASC, `PGPBatchSeq` ASC) VISIBLE,
  CONSTRAINT `FK_PGP_PostingGroupId`
    FOREIGN KEY (`PostingGroupId`)
    REFERENCES `pg`.`PostingGroup` (`PostingGroupId`)
    ON DELETE NO ACTION
    ON UPDATE NO ACTION,
  CONSTRAINT `FK_PGP_PostingGroupStatusId`
    FOREIGN KEY (`PostingGroupStatusId`)
    REFERENCES `pg`.`RefStatus` (`StatusId`)
    ON DELETE NO ACTION
    ON UPDATE NO ACTION,
