CREATE TABLE IF NOT EXISTS `pg`.`PostingGroup` (
  `PostingGroupId` INT NOT NULL,
  `PostingGroupCode` VARCHAR(100) NOT NULL,
  `PostingGroupName` VARCHAR(250) NOT NULL,
  `PostingGroupDesc` LONGTEXT NOT NULL DEFAULT 'Unknown',
  `PostingGroupCategoryCode` VARCHAR(20) NOT NULL DEFAULT 'UNK',
  `PostingGroupCategoryName` VARCHAR(250) NOT NULL DEFAULT 'Unknown',
  `PostingGroupCategoryDesc` LONGTEXT NOT NULL DEFAULT 'The category for this record is unknown.',
  `ProcessingMethodCode` VARCHAR(20) NOT NULL DEFAULT 'ADFP',
  `ProcessingModeCode` VARCHAR(20) NOT NULL DEFAULT 'NORM',
  `IntervalCode` VARCHAR(20) NOT NULL DEFAULT 'IMM',
  `IntervalLength` INT NOT NULL DEFAULT 1,
  `SSISFolder` VARCHAR(255) NOT NULL DEFAULT 'N/A',
  `SSISProject` VARCHAR(255) NOT NULL DEFAULT 'N/A',
  `SSISPackage` VARCHAR(255) NOT NULL DEFAULT 'N/A',
  `DataFactoryName` VARCHAR(255) NOT NULL DEFAULT 'N/A',
  `DataFactoryPipeline` VARCHAR(255) NOT NULL DEFAULT 'N/A',
  `GlueWorkflow` VARCHAR(255) NOT NULL DEFAULT 'N/A',
  `JobName` VARCHAR(255) NOT NULL DEFAULT 'N/A',
  `SQLStoredProcedure` VARCHAR(255) NOT NULL DEFAULT 'N/A',
  `IsActive` TINYINT(1) NOT NULL DEFAULT 1,
  `IsRoot` TINYINT(1) NOT NULL DEFAULT 0,
  `NextExecutionDtm` DATETIME(6) NOT NULL DEFAULT '1900-01-01 00:00:00.000',
  `RetryMax` INT NOT NULL DEFAULT 0,
  `RetryIntervalLength` INT NOT NULL DEFAULT 0,
  `RetryIntervalCode` VARCHAR(20) NOT NULL DEFAULT 'N/A',
  `SLAEndTimeInMinutes` INT NOT NULL DEFAULT 0,
  `CreatedBy` VARCHAR(50) NOT NULL,
  `CreatedDtm` DATETIME(6) NOT NULL,
  `ModifiedBy` VARCHAR(50) NULL,
  `ModifiedDtm` DATETIME(6) NULL,
  PRIMARY KEY (`PostingGroupId`),
  UNIQUE INDEX `UQ_PostingGroup__PostingGroupCode` (`PostingGroupCode` ASC) VISIBLE,
  CONSTRAINT `FK_ProcessingMethod_PostingGroup__ProcessingMethodCode`
    FOREIGN KEY (`ProcessingMethodCode`)
    REFERENCES `pg`.`RefProcessingMethod` (`ProcessingMethodCode`)
    ON DELETE NO ACTION
    ON UPDATE NO ACTION,
  CONSTRAINT `FK_Interval_PostingGroup__RetryIntervalCode`
    FOREIGN KEY (`RetryIntervalCode`)
    REFERENCES `ctl`.`RefInterval` (`IntervalCode`)
    ON DELETE NO ACTION
    ON UPDATE NO ACTION,
  CONSTRAINT `FK_ProcessingMode_PostingGroup__ProcessingModeCode`
    FOREIGN KEY (`ProcessingModeCode`)
    REFERENCES `pg`.`RefProcessingMode` (`ProcessingModeCode`)
    ON DELETE NO ACTION
    ON UPDATE NO ACTION,
  CONSTRAINT `FK_Interval_PostingGroup__IntervalCode`
    FOREIGN KEY (`IntervalCode`)
    REFERENCES `ctl`.`RefInterval` (`IntervalCode`)
    ON DELETE NO ACTION
    ON UPDATE NO ACTION);

