-- -------------------------------------------------------------------------------
-- 	select	 @StepName			= 'Insert new record into Posting Group'
-- 			,@StepNumber		= @StepNumber + 1
-- 			,@StepOperation		= 'insert'
-- 			,@StepDesc			= 'Preparing a new record for posting group.'
-- 
-- 	insert into pg.PostingGroup(
