-- 
-- 
-- 
-- 	if exists
-- 	( 
-- 		select	 top 1 1
-- 		from	 pg.PostingGroupProcessing	  pgp
-- 		where	 pgp.PostingGroupBatchId	= @pPostingGroupBatchId
-- 		and		 pgp.PostingGroupId			= @pPostingGroupId
-- 		and		 pgp.PGPBatchSeq			= @pPostingGroupBatchSeq
