-- 			join	   pg.PostingGroup				  pgC
-- 			on		  pgC.PostingGroupId			= pgd.ChildId
-- 			where	 pgpP.PostingGroupBatchId		= @pPostingGroupBatchId
-- 			and		 pgpP.PostingGroupId			= @pPostingGroupId
-- 			and		 pgpP.PGPBatchSeq				= @pPostingGroupBatchSeq
