-- 	else if  @APIResponse = 'PipelineIsRunning'
-- 		select 	  @pExecuteProcessStatus = 'IAR' -- Instance already running.
-- 	else
-- 		select 	  @pExecuteProcessStatus = 'ISF' -- Instance run failed.
-- 
-- 	EXEC sp_OADestroy @HTTPObject
-- 
-- 	-------------------------------------------------------------------------------
-- 	-- Trigger Data Factory  - End
