-- 			
-- 			if 	@ErrNum < 50000	
-- 				select	 @ErrNum	= @ErrNum + 1000000 -- Need to increase number to throw message.
-- 
-- 			;throw	 @ErrNum, @ErrMsg, 1
-- 		end catch
-- 
-- 		select	 @LoopCount							= @LoopCount + 1
-- 				,@SSISFolder						= 'N/A'
-- 				,@SSISProject						= 'N/A'
-- 				,@SSISPackage						= 'N/A'
-- 				,@DataFactoryName					= 'N/A'
-- 				,@DataFactoryPipeline				= 'N/A'
