-- 				,@ExecutingChildPostingGroupId		= -1
-- 				,@CurPGPBatchSeq					= -1
-- 				,@NextPGPBatchSeq					= -1
-- 				,@PostingGroupProcessingIdToExecute	= -1
-- 				,@PostingGroupCodeToExecute			= 'UNK'
