-- DELIMITER $$
-- 
-- DELIMITER $$
-- USE `pg`$$
-- CREATE FUNCTION [pg].[fn_GetPostingGroupProcessingStatus] (
--      @pPGId                         int
--     ,@pPGPBId                       int
-- 	,@pPGPSeq						int)
-- RETURNS varchar(20)
-- AS
-- 
-- /*****************************************************************************
-- file:           fn_GetPostingGroupProcessingStatus.sql
-- name:           fn_GetPostingGroupProcessingStatus
-- purpose:        Gets the status of a given posting group.
-- 
-- exec ctl.fnGetPostingGroupProcessingStatus 8,2,'PC'
-- 
-- parameters:
--     PC    Posting Group Complete
--     PF    Posting Group Failed
--     PP    Posting Group Processing
--     PQ    Posting Group Queued
-- 
-- 
-- called by:    
-- calls:         N/A  
-- 
-- author:         ffortunato
-- date:           20161018
-- 
-- 
-- *******************************************************************************
--       change history
-- *******************************************************************************
-- date      author         description
-- --------  -------------  ------------------------------------------------------
-- 20161205  ffortunato     initial iteration.
-- 20181004  ffortunato     Need to add the sequence as a parameter as well.
-- ******************************************************************************/
-- 
-- -------------------------------------------------------------------------------
-- --  declarations
-- -------------------------------------------------------------------------------
-- 
-- BEGIN
-- 
-- -------------------------------------------------------------------------------
-- --  declarations
-- -------------------------------------------------------------------------------
-- 
-- declare 
-- 		 @StatusCode			varchar(20)
-- 		,@pPostingGroupBatchId	int
-- 		,@PostingGroupId		int
-- 
-- select	@StatusCode				= RS.StatusCode
-- from	pg.PostingGroupProcessing  PGP
-- join	pg.RefStatus               RS
-- on		PGP.PostingGroupStatusId= RS.StatusId
-- where	PGP.PostingGroupBatchId	= @pPGPBId
-- and		PGP.PostingGroupId		= @pPGId
-- and		PGP.PGPBatchSeq			= @pPGPSeq
-- 
-- 
-- RETURN @StatusCode
-- 
-- END
-- $$
-- 
-- DELIMITER ;
-- 
-- ----------------------------------------------------------------------------
-- Routine pg.fn_GetPostingGroupProcessingDetails
-- ----------------------------------------------------------------------------
-- DELIMITER $$
-- 
-- DELIMITER $$
-- USE `pg`$$
-- CREATE FUNCTION [pg].[fn_GetPostingGroupProcessingDetails] (
-- 		 @pPostingGroupBatchId		int				= -1
-- 		,@pPostingGroupId			int				= -1
-- 		,@pPostingGroupBatchSeq		int				= -1
-- 		,@pChildPostingGroupCode	varchar(100)	= 'N/A'
-- 		,@pETLExecutionId			int				= -1
-- 		,@pPathId					int				= -1
-- 		,@pVerbose					bit				= 0)
-- 
-- /*****************************************************************************
-- File:		fn_GetPostingGroupProcessingDetails.sql
-- Name:		fn_GetPostingGroupProcessingDetails
-- Purpose:    Allows for the retrieval of detailed Posting Group Processing
-- 			information. This includes parent and child details. This 
-- 			procedure does _not_ traverse the dependencies to the leaf level, 
-- 			just next of kin.
-- 
-- 
-- 
-- select  * from pg.fn_GetPostingGroupProcessingDetails (
-- 		  3
-- 		, 109
-- 		, 3
-- 		,'PUBR01-SUBR01-PUBN01-ACCT'
-- 		, -1
-- 		, -1
-- 		, 0)
-- 
-- Parameters:	@pIssueID - IssueID to retrieve details of
-- 
-- Called by: ETL
-- Calls:          
-- 
-- Errors:		
-- 
-- Author:		ffortunato
-- Date:		20181011
-- 
-- *******************************************************************************
--        CHANGE HISTORY
-- *******************************************************************************
-- Date		Author			Description
-- --------	-------------	---------------------------------------------------
-- 20181011	ffortunato		Initial iteration.
-- 
-- ******************************************************************************/
-- 
-- RETURNS @ReturnTable TABLE
-- (
-- 	 ParentPostingGroupProcessingId	bigint
-- 	,ParentPostingGroupBatchId		int
-- 	,ParentPostingGroupId			int
-- 	,ParentPostingGroupStatusId		int
-- 	,ParentPGPBatchSeq				bigint
-- 	,ChildPostingGroupProcessingId	bigint
-- 	,ChildPostingGroupBatchId		int
-- 	,ChildPostingGroupId			int
-- 	,ChildPostingGroupStatusId		int
-- 	,ChildPGPBatchSeq				bigint
-- 		--,ChildRetryCount				int
-- 	,ChildIssueId					bigint
-- 	,ChildDistributionId			bigint
-- 	,ChildPostingGroupCode			varchar(100)
-- )
-- AS
-- BEGIN
-- 	if exists
-- 	( 
-- 		select	 top 1 1
-- 		from	 pg.PostingGroupProcessing	  pgp
-- 		where	 pgp.PostingGroupBatchId	= @pPostingGroupBatchId
-- 		and		 pgp.PostingGroupId			= @pPostingGroupId
-- 		and		 pgp.PGPBatchSeq			= @pPostingGroupBatchSeq
-- 	)
-- 	begin
-- 		if (@pChildPostingGroupCode <> 'N/A')
-- 		begin	
-- 			insert into @ReturnTable
--   			select	 pgpP.PostingGroupProcessingId	ParentPostingGroupProcessingId
-- 					,pgpP.PostingGroupBatchId		ParentPostingGroupBatchId
-- 					,pgpP.PostingGroupId			ParentPostingGroupId
-- 					,pgpP.PostingGroupStatusId		ParentPostingGroupStatusId
-- 					,pgpP.PGPBatchSeq				ParentPGPBatchSeq
-- 	--				,pgpP.RetryCount				ParentRetryCount
-- 	--				,pgpP.IssueId					ParentIssueId
-- 	--				,pgpP.DistributionId			ParentDistributionId
-- 	--				, pgP.PostingGroupCode			ParentPostingGroupCode
-- 					,pgpC.PostingGroupProcessingId	ChildPostingGroupProcessingId
-- 					,pgpC.PostingGroupBatchId		ChildPostingGroupBatchId
-- 					,pgpC.PostingGroupId			ChildPostingGroupId
-- 					,pgpC.PostingGroupStatusId		ChildPostingGroupStatusId
-- 					,pgpC.PGPBatchSeq				ChildPGPBatchSeq
-- 	--				,pgpC.RetryCount				ChildRetryCount
-- 					,isnull(pgpC.IssueId,-1)		ChildIssueId
-- 					,isnull(pgpC.DistributionId,-1)	ChildDistributionId
-- 					, pgC.PostingGroupCode			ChildPostingGroupCode
-- 			from	   pg.PostingGroupProcessing	  pgpP
-- 			join	   pg.PostingGroupDependency	  pgd
-- 			on		 pgpP.PostingGroupId			= pgd.ParentId
-- 	--		join	   pg.PostingGroup				  pgP
-- 	--		on		  pgP.PostingGroupId			= pgd.ParentId
-- 			join	   pg.PostingGroupProcessing	  pgpC
-- 			on		 pgpC.PostingGroupId			= pgd.ChildId
-- 			join	   pg.PostingGroup				  pgC
-- 			on		  pgC.PostingGroupId			= pgd.ChildId
-- 			where	 pgpP.PostingGroupBatchId		= @pPostingGroupBatchId
-- 			and		 pgpP.PostingGroupId			= @pPostingGroupId
-- 			and		 pgpP.PGPBatchSeq				= @pPostingGroupBatchSeq
-- 			and		 pgpC.PostingGroupBatchId		= @pPostingGroupBatchId
-- 			and		 pgpC.PGPBatchSeq				= @pPostingGroupBatchSeq
-- 			and		  pgC.PostingGroupCode			= @pChildPostingGroupCode
-- 		end --ChildPostingGroupProvided
-- 		else
-- 		begin
-- 			insert into @ReturnTable
--   			select	 pgpP.PostingGroupProcessingId	ParentPostingGroupProcessingId
-- 					,pgpP.PostingGroupBatchId		ParentPostingGroupBatchId
-- 					,pgpP.PostingGroupId			ParentPostingGroupId
-- 					,pgpP.PostingGroupStatusId		ParentPostingGroupStatusId
-- 					,pgpP.PGPBatchSeq				ParentPGPBatchSeq
-- 	--				,pgpP.RetryCount				ParentRetryCount
-- 	--				,pgpP.IssueId					ParentIssueId
-- 	--				,pgpP.DistributionId			ParentDistributionId
-- 	--				, pgP.PostingGroupCode			ParentPostingGroupCode
-- 					,pgpC.PostingGroupProcessingId	ChildPostingGroupProcessingId
-- 					,pgpC.PostingGroupBatchId		ChildPostingGroupBatchId
-- 					,pgpC.PostingGroupId			ChildPostingGroupId
-- 					,pgpC.PostingGroupStatusId		ChildPostingGroupStatusId
-- 					,pgpC.PGPBatchSeq				ChildPGPBatchSeq
-- 	--				,pgpC.RetryCount				ChildRetryCount
-- 					,isnull(pgpC.IssueId,-1)		ChildIssueId
-- 					,isnull(pgpC.DistributionId,-1)	ChildDistributionId
-- 					, pgC.PostingGroupCode			ChildPostingGroupCode
-- 			from	   pg.PostingGroupProcessing	  pgpP
-- 			join	   pg.PostingGroupDependency	  pgd
-- 			on		 pgpP.PostingGroupId			= pgd.ParentId
-- 	--		join	   pg.PostingGroup				  pgP
-- 	--		on		  pgP.PostingGroupId			= pgd.ParentId
-- 			join	   pg.PostingGroupProcessing	  pgpC
-- 			on		 pgpC.PostingGroupId			= pgd.ChildId
-- 			join	   pg.PostingGroup				  pgC
-- 			on		  pgC.PostingGroupId			= pgd.ChildId
-- 			where	 pgpP.PostingGroupBatchId		= @pPostingGroupBatchId
-- 			and		 pgpP.PostingGroupId			= @pPostingGroupId
-- 			and		 pgpP.PGPBatchSeq				= @pPostingGroupBatchSeq
-- 			and		 pgpC.PostingGroupBatchId		= @pPostingGroupBatchId
-- 			and		 pgpC.PGPBatchSeq				= @pPostingGroupBatchSeq
-- 		end -- Not child posting ggroup code provided.
-- 	end
-- 	return
-- end
-- $$
-- 
-- DELIMITER ;
-- 
-- ----------------------------------------------------------------------------
-- Trigger pg.trg_NotifyCompleteDistribution
-- ----------------------------------------------------------------------------
-- DELIMITER $$
-- USE `pg`$$
-- 
-- CREATE TRIGGER pg.trg_NotifyCompleteDistribution ON [pg].[PostingGroupProcessing] FOR  UPDATE AS
-- /******************************************************************************
-- file:           trg_NotifyCompleteDistribution.sql
-- name:           trg_NotifyCompleteDistribution
-- 
-- purpose:        this trigger sits on the PostingGroupProcessing table. when a 
-- 				PostingGroupProcessing status is updated the trigger determines if the 
-- 				associated distribtuion status can be updated.
-- 
-- called by:      update on pg.PostingGroupProcessing
-- calls:          
-- 
-- author:         ffortunato
-- date:           20181011
-- 
-- *******************************************************************************
--        change history
-- *******************************************************************************
-- date		author			description
-- --------	-------------	---------------------------------------------------
-- 20181011	ffortunato		initial iteration
-- 20210413	ffortunato		lots of ints here should be bigints...
-- 
-- ******************************************************************************/
-- 
-- declare 
--      @err						int				= 0
--     ,@ErrMsg					varchar(255)	= 'trg_NotifyCompleteDistribution (trigger) failed.' + Char(13)
--     ,@Start						datetime		= GETDATE()
--     ,@PublisherId				int				= -1
--     ,@PublicationId				int				= -1
--     ,@IssueId					int				= -1
-- 	,@RefStatsType				varchar(100)	= 'Distribution'
-- 	,@DistributionId			bigint			= -1
-- 	,@DistributionStatusId		int				= -1
--     ,@DistributionStatusCode	varchar(20)		= 'DN'
-- 	,@ChildPostingGroupId		bigint				= -1
-- 	,@PostingGroupProcessingId	bigint			= -1
-- 	,@PostingGroupId			int				= -1
-- 	,@PostingGroupBatchId		bigint			= -1
-- 	,@PGPBatchSeq				bigint			= -1
-- 	,@PostingGroupProcessingStatusId	int		= -1
-- 	,@PostingGroupProcessingStatusCode	varchar(20) = 'N/A'
--     ,@CreatedBy					varchar(30)		= SYSTEM_USER
-- 	,@Verbose					bit				= 0
-- 	,@TotalCount				int				= -1
-- 	,@MetCount					int				= -2
-- 	,@LoopCount					int				= 1
-- 	,@MaxLoopCount				int				= -2
-- 	,@ChildLoopCount			int				= 1
-- 	,@ChildMaxLoopCount			int				= -2
-- 
-- declare @Inserted table (
-- 	 InsertedId							int identity (1,1)		not null
-- 	,PostingGroupProcessingId			bigint		not null
-- 	,PostingGroupId						int			not null
-- 	,PostingGroupBatchId				int			not null
-- 	,PGPBatchSeq						bigint		not null
-- 	,PostingGroupProcessingStatusId		int			not null
-- 	,PostingGroupProcessingStatusCode	varchar(20) not null
-- )
-- 
-- declare @AllMyChildren table (
-- 	 AllMyChildrenId					int identity (1,1)		not null
-- 	,ChildPostingGroupId				bigint		not null
-- 	,PostingGroupBatchId				bigint		not null
-- 	,PGPBatchSeq						bigint		not null
-- 	,PostingGroupProcessingStatusId		int			not null
-- 	,DistributionId						bigint		not null
-- )
-- 
-- begin try
-- 
-- 	insert into @Inserted (
-- 			 PostingGroupProcessingId
-- 			,PostingGroupId
-- 			,PostingGroupBatchId
-- 			,PGPBatchSeq
-- 			,PostingGroupProcessingStatusId
-- 			,PostingGroupProcessingStatusCode	
-- 	)
-- 	select	 ins.PostingGroupProcessingId
-- 			,ins.PostingGroupId
-- 			,ins.PostingGroupBatchId
-- 			,ins.PGPBatchSeq
-- 			,ins.PostingGroupStatusId
-- 			,rs.StatusCode
-- 	from	 inserted					  ins
-- 	join	 pg.RefStatus				  rs
-- 	on		 ins.PostingGroupStatusId	= rs.StatusId
-- 	where	 rs.StatusCode				in ('PC','PF')
-- 
-- 	-- Technically there should never be more than one records inserted at a time.
-- 	-- Just incase we are loading this into a while loop.
-- 
-- 	select	 @MaxLoopCount = max(InsertedId)
-- 	from	 @Inserted
-- 
-- 	while	 @LoopCount <= @MaxLoopCount
-- 	begin
-- 
-- 		select	 @PostingGroupProcessingId			= ins.PostingGroupProcessingId
-- 				,@PostingGroupId					= ins.PostingGroupId
-- 				,@PostingGroupBatchId				= ins.PostingGroupBatchId
-- 				,@PGPBatchSeq						= ins.PGPBatchSeq
-- 				,@PostingGroupProcessingStatusCode	= ins.PostingGroupProcessingStatusCode
-- 				,@PostingGroupProcessingStatusId    = ins.PostingGroupProcessingStatusId
-- 		from	 @Inserted							  ins
-- 		where	 InsertedId							= @LoopCount
-- 
-- 		-- base line the Parent process that just completed.
-- 		-- Find that parents children
-- 		-- Find those children's parents
-- 		-- Count the total number of parents.
-- 
-- 		insert into @AllMyChildren (
-- 				 ChildPostingGroupId
-- 				,PostingGroupBatchId
-- 				,PGPBatchSeq
-- 				,PostingGroupProcessingStatusId
-- 				,DistributionId)
-- 		select	 pgd.ChildId
-- 				,@PostingGroupBatchId
-- 				,@PGPBatchSeq
-- 				,@PostingGroupProcessingStatusId
-- 				,-3
-- 		from	pg.PostingGroupDependency			  pgd
-- 		where	pgd.ParentId						= @PostingGroupId  -- this is the parent that fired the trigger
-- 		group by pgd.ChildId
-- 
-- 		update										  amc
-- 		set		 DistributionId						= isnull(pgp.DistributionId, -2)
-- 		from	 @AllMyChildren						  amc
-- 		join	 pg.PostingGroupProcessing			  pgp
-- 		on		pgp.PostingGroupId					= ChildPostingGroupId
-- 		where	pgp.PostingGroupBatchId				= @PostingGroupBatchId
-- 		and		pgp.PGPBatchSeq						= @PGPBatchSeq
-- 		and		pgp.PostingGroupStatusId			= @PostingGroupProcessingStatusId
-- 
-- 		-- Now check the indiivdual children's parents for completion. 
-- 		-- If all parents are complete notify datahub.
-- 
-- 		select	 @ChildMaxLoopCount = max(AllMyChildrenId)
-- 		from	 @AllMyChildren
-- 
-- 		while	 @ChildLoopCount <= @ChildMaxLoopCount
-- 		begin
-- 
-- 			select	 @ChildPostingGroupId				= amc.ChildPostingGroupId
-- 					,@PostingGroupBatchId				= amc.PostingGroupBatchId
-- 					,@PGPBatchSeq						= amc.PGPBatchSeq
-- 					,@PostingGroupProcessingStatusId    = amc.PostingGroupProcessingStatusId
-- 					,@DistributionId					= amc.DistributionId
-- 			from	 @AllMyChildren						  amc
-- 			where	 AllMyChildrenId					= @ChildLoopCount
-- 
-- 			select	 @TotalCount						= count(1)
-- 			from	 @AllMyChildren						  amc
-- 			join	 pg.PostingGroupDependency			  pgd
-- 			on		amc.ChildPostingGroupId				= pgd.ChildId
-- 			where	 AllMyChildrenId					= @ChildLoopCount
-- 
-- 			select	 @MetCount							= count(1)
-- 			from	 @AllMyChildren						  amc
-- 			join	  pg.PostingGroupDependency			  pgdC
-- 			on		amc.ChildPostingGroupId				= pgdC.ChildId
-- 			join	  pg.PostingGroupProcessing			  pgpP
-- 			on		pgdC.ParentId						= pgpP.PostingGroupId
-- 			and		pgpP.PostingGroupBatchId			= amc.PostingGroupBatchId
-- 			and		pgpP.PostingGroupStatusId			= amc.PostingGroupProcessingStatusId
-- 			and		pgpP.PGPBatchSeq					= amc.PGPBatchSeq
-- 			where	 AllMyChildrenId					= @ChildLoopCount
-- 
-- 			if	(@PostingGroupProcessingStatusCode = 'PF')
-- 			begin
-- 				update	 dis
-- 				set		 StatusId			= (select StatusId from ctl.RefStatus where StatusCode = 'DF')
-- 						,ModifiedBy			= @CreatedBy
-- 						,ModifiedDtm		= @Start
-- 				from	 ctl.Distribution	  dis
-- 				where	 dis.DistributionId	= @DistributionId
-- 
-- 			end -- (@@PostingGroupProcessingStatusCode = 'PF')
-- 
-- 			else if	((@MetCount = @TotalCount) and (@PostingGroupProcessingStatusCode = 'PC'))
-- 			begin
-- 					update	 dis
-- 					set		 StatusId			= (select StatusId from ctl.RefStatus where StatusCode = 'DC')
-- 							,ModifiedBy			= @CreatedBy
-- 							,ModifiedDtm		= @Start
-- 					from	 ctl.Distribution	  dis
-- 					where	 dis.DistributionId	= @DistributionId
-- 			end  -- (@MetCount =@TotalCount)
-- 
-- 			select	 @ChildLoopCount					= @ChildLoopCount + 1	
-- 					,@ChildPostingGroupId				= -1
-- 					,@PostingGroupBatchId				= -1
-- 					,@PGPBatchSeq						= -1
-- 					,@DistributionId					= -3
-- 
-- 		end -- while for the children
-- 		select	 @LoopCount							= @LoopCount + 1	
-- 				,@PostingGroupProcessingId			= -1
-- 				,@PostingGroupBatchId				= -1
-- 				,@PGPBatchSeq						= -1
-- 				,@PostingGroupProcessingStatusCode	= 'PF'
-- 				,@PostingGroupProcessingStatusId    = -1
-- 
-- 	end -- While loop for _all_ updated records.
-- end try
-- 
-- 	begin catch
-- 		select @ErrMsg	= @ErrMsg + char(13)  + 	
-- 						' @DistributionId = ' + isnull(cast(@DistributionId as varchar(100)),'NULL') + ' ' 
-- 		select @ErrMsg = @ErrMsg + char(13)  + ERROR_MESSAGE()
-- 		raiserror (@ErrMsg,-1,-1)
-- 
-- 	end catch
-- ;
SET FOREIGN_KEY_CHECKS = 1;
